'use strict';
const $=id=>document.getElementById(id),GiB=1024**3;
let selected=null,wave=null,offset=0,total=0,dirty=false,units=[],selectionSource=null,audioContext=null,loadGeneration=0,listGeneration=0;
function notice(text=''){$('notice').textContent=text;$('notice').hidden=!text;}
const guard=fn=>async(...args)=>{try{await fn(...args);}catch(e){notice(e.message);}};
async function api(path,options={}){const r=await fetch(path,options);if(r.status===401){location.assign('/?next=/training');throw new Error('Sign in to review recordings.');}if(!r.ok){let detail;try{detail=(await r.json()).detail;}catch{}throw new Error(typeof detail==='string'?detail:`Request failed (${r.status}). Check your entries and try again.`);}return r.json();}
const send=(path,method,body={})=>api(path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function node(tag,text,cls=''){const n=document.createElement(tag);n.textContent=text;n.className=cls;return n;}
function warning(status){return !status.ready?'Archive unavailable. Voice processing continues.':!status.settings.enabled?'Collection is paused. Existing recordings remain available.':status.warning||(status.full?'Archive limit or disk reserve reached. Increase the limit or make space to resume collection. Voice processing continues.':'');}
async function refreshStatus(fill=false){const s=await api('/api/training/status');$('recordCount').textContent=s.records;$('unreviewedCount').textContent=s.labels.unreviewed;$('positiveCount').textContent=s.labels.positive;$('storageSummary').textContent=s.ready?`${(s.used_bytes/GiB).toFixed(3)} / ${(s.settings.max_bytes/GiB).toFixed(2)} GiB used · ${(s.free_bytes/GiB).toFixed(1)} GiB free`:'';$('archiveWarning').textContent=warning(s);$('archiveWarning').hidden=!$('archiveWarning').textContent;if(fill){$('enabled').checked=s.settings.enabled;$('maxGiB').value=s.settings.max_bytes/GiB;$('reserveGiB').value=s.settings.min_free_bytes/GiB;$('maxRecords').value=s.settings.max_records;$('archivePath').textContent=s.directory?`Stored on this head-end: ${s.directory}`:'';}}
async function list(){const generation=++listGeneration;const p=new URLSearchParams({label:$('labelFilter').value,unit_id:$('unitFilter').value,q:$('search').value,limit:25,offset});const data=await api('/api/training/recordings?'+p);if(generation!==listGeneration)return;total=data.total;$('recordings').replaceChildren();for(const r of data.records){const button=node('button','','recording');button.type='button';button.dataset.id=r.id;button.setAttribute('aria-pressed',String(selected?.id===r.id));button.append(node('span',`${r.device_name} · ${r.label}`),node('small',`${new Date(r.recorded_at*1000).toLocaleString()} · ${r.trigger==='wake'?'Automatic wake':'Manual recording'} · ${(r.duration_ms/1000).toFixed(2)} s`),node('span',r.transcript||`Transcription: ${r.transcription_status}`,'excerpt'));button.onclick=guard(async()=>{if(dirty&&!confirm('Leave without saving this review?'))return;await openRecord(r.id);});$('recordings').append(button);}if(!data.records.length)$('recordings').append(node('div','No recordings match. Completed device interactions will appear here.','empty'));$('prev').disabled=offset===0;$('next').disabled=offset+25>=total;$('pageInfo').textContent=total?`${offset+1}–${Math.min(offset+25,total)} of ${total}`:'0 recordings';}
function stopSelection(){if(selectionSource){try{selectionSource.stop();}catch{}selectionSource=null;}}
function bounds(){return [$('phraseStart').value===''?null:Math.round(Number($('phraseStart').value)*1000),$('phraseEnd').value===''?null:Math.round(Number($('phraseEnd').value)*1000)];}
function draw(){const canvas=$('waveform'),rect=canvas.getBoundingClientRect();if(!rect.width)return;const scale=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*scale);canvas.height=130*scale;const c=canvas.getContext('2d');c.scale(scale,scale);const w=rect.width,h=130;c.clearRect(0,0,w,h);if(!wave||!selected)return;const [start,end]=bounds(),duration=selected.duration_ms;if(start!==null&&end!==null){c.fillStyle='#254f46';c.fillRect(start/duration*w,0,(end-start)/duration*w,h);}c.strokeStyle='#86dfcd';c.beginPath();wave.peaks.forEach((p,i)=>{const x=(i+.5)/wave.peaks.length*w;c.moveTo(x,h/2-p*53);c.lineTo(x,h/2+p*53);});c.stroke();c.strokeStyle='#efc28a';const pre=selected.preroll_ms/duration*w;c.beginPath();c.moveTo(pre,0);c.lineTo(pre,h);c.stroke();c.strokeStyle='#ffffff';const play=$('player').currentTime*1000/duration*w;c.beginPath();c.moveTo(play,0);c.lineTo(play,h);c.stroke();}
function transcript(r){$('transcript').textContent=r.transcript||'No transcript available.';$('transcriptStatus').textContent=`${r.transcription_status}${r.transcription_error?' · '+r.transcription_error:''}`;$('retry').disabled=r.audio_status!=='ready'||['pending','queued','running','cancelling'].includes(r.transcription_status);}
async function openRecord(id){const generation=++loadGeneration;const r=await api('/api/training/recordings/'+id);if(generation!==loadGeneration)return;stopSelection();$('player').pause();selected=r;wave=null;dirty=false;history.replaceState(null,'','#'+id);$('emptyReview').hidden=true;$('review').hidden=false;$('recordTitle').textContent=r.device_name;$('recordLabel').textContent=r.label;$('provenance').textContent=`${new Date(r.recorded_at*1000).toLocaleString()} · ${r.trigger==='wake'?'Automatic wake':'Manual recording'} · ${(r.duration_ms/1000).toFixed(2)} s total · ${(r.preroll_ms/1000).toFixed(2)} s pre-trigger`;$('recordWarning').textContent=r.archive_error;$('recordWarning').hidden=!r.archive_error;$('audioTools').hidden=r.audio_status!=='ready';$('player').removeAttribute('src');$('player').load();$('gain').value='0';if(r.audio_status==='ready')$('player').src=`/api/training/recordings/${id}/audio`;$('download').href=`/api/training/recordings/${id}/audio`;$('phraseStart').value=r.phrase_start_ms===null?'':r.phrase_start_ms/1000;$('phraseEnd').value=r.phrase_end_ms===null?'':r.phrase_end_ms/1000;for(const key of ['phraseStart','phraseEnd'])$(key).max=r.duration_ms/1000;$('reviewLabel').value=r.label;$('cueStatus').value=r.cue_status;$('reviewRoom').value=r.room;$('reviewSpeaker').value=r.speaker;$('reviewDistance').value=r.distance;$('reviewSession').value=r.collection_session;$('reviewNotes').value=r.notes;transcript(r);$('metadata').replaceChildren();for(const [name,value] of Object.entries({'Recording ID':r.id,'Session ID':r.session_id,'Device ID':r.unit_id,'Wake model':r.wake_model_id||'Not reported','Firmware':r.firmware||'Not reported','Original SHA-256':r.sha256,'Audio':`${r.audio_status} · 16 kHz mono, 16-bit PCM`,'Timestamp source':'Head-end upload start','Capture after trigger':`${r.capture_ms} ms`,'Endpoint':`${r.endpoint_mode} ${r.endpoint_reason}`,'Transcription gain':r.transcription_details.input_gain??'Not available'}))$('metadata').append(node('dt',name),node('dd',String(value)));document.querySelectorAll('.recording').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.id===id)));if(r.audio_status==='ready'){const data=await api(`/api/training/recordings/${id}/waveform`);if(generation!==loadGeneration)return;wave=data;}draw();}
async function loadContext(){const unitId=$('collectionUnit').value;if(!unitId)return;const c=await api('/api/training/contexts/'+unitId);if(unitId!==$('collectionUnit').value)return;$('contextRoom').value=c.room;$('contextSpeaker').value=c.speaker;$('contextDistance').value=c.distance;$('contextSession').value=c.collection_session;$('manualListen').disabled=!units.find(u=>u.id===unitId)?.online;}
async function saveContext(){return send('/api/training/contexts/'+$('collectionUnit').value,'PUT',{room:$('contextRoom').value,speaker:$('contextSpeaker').value,distance:$('contextDistance').value,collection_session:$('contextSession').value});}
$('contextForm').onsubmit=guard(async e=>{e.preventDefault();await saveContext();notice('Collection tags saved for future recordings.');});$('collectionUnit').onchange=guard(loadContext);
$('manualListen').onclick=guard(async()=>{const b=$('manualListen');b.disabled=true;try{await saveContext();await send(`/api/units/${$('collectionUnit').value}/listen`,'POST');notice('Listen requested. Wait for the device to turn green, then say “Hey Adam” and your command. Refresh the list after recording finishes.');}finally{b.disabled=false;}});
$('settingsForm').onsubmit=guard(async e=>{e.preventDefault();await send('/api/training/settings','PUT',{enabled:$('enabled').checked,max_bytes:Math.round(Number($('maxGiB').value)*GiB),min_free_bytes:Math.round(Number($('reserveGiB').value)*GiB),max_records:Number($('maxRecords').value)});await refreshStatus(true);notice('Storage settings saved. Existing recordings are retained.');});
$('filterForm').onsubmit=guard(async e=>{e.preventDefault();offset=0;await list();await refreshStatus();});$('labelFilter').onchange=$('unitFilter').onchange=guard(async()=>{offset=0;await list();});$('prev').onclick=guard(async()=>{offset=Math.max(0,offset-25);await list();});$('next').onclick=guard(async()=>{offset+=25;await list();});
$('reviewForm').oninput=()=>{dirty=true;draw();};$('reviewForm').onsubmit=guard(async e=>{e.preventDefault();if(!selected)return;const [start,end]=bounds();const r=await send(`/api/training/recordings/${selected.id}/review`,'PUT',{revision:selected.revision,label:$('reviewLabel').value,phrase_start_ms:start,phrase_end_ms:end,cue_status:$('cueStatus').value,room:$('reviewRoom').value,speaker:$('reviewSpeaker').value,distance:$('reviewDistance').value,collection_session:$('reviewSession').value,notes:$('reviewNotes').value});selected=r;dirty=false;$('recordLabel').textContent=r.label;notice('Review saved. No model has been trained or changed.');await list();await refreshStatus();});
for(const [button,field] of [['markStart','phraseStart'],['markEnd','phraseEnd']])$(button).onclick=()=>{if(!selected)return;$(field).value=Math.min(selected.duration_ms/1000,$('player').currentTime).toFixed(3);dirty=true;draw();};$('clearBounds').onclick=()=>{$('phraseStart').value='';$('phraseEnd').value='';dirty=true;draw();};
$('gain').onchange=()=>{if(!selected)return;const at=$('player').currentTime;stopSelection();$('player').src=`/api/training/recordings/${selected.id}/audio?gain_db=${$('gain').value}`;$('player').addEventListener('loadedmetadata',()=>{$('player').currentTime=at;},{once:true});};
$('playSelection').onclick=guard(async()=>{const [start,end]=bounds();if(!selected||start===null||end===null||start>=end||end>selected.duration_ms)throw new Error('Choose valid phrase boundaries first.');const id=selected.id,generation=loadGeneration;stopSelection();$('player').pause();audioContext ||= new AudioContext();await audioContext.resume();const response=await fetch(`/api/training/recordings/${id}/audio?gain_db=${$('gain').value}`);if(!response.ok)throw new Error('Audio could not be loaded.');const buffer=await audioContext.decodeAudioData(await response.arrayBuffer());if(generation!==loadGeneration)return;stopSelection();selectionSource=audioContext.createBufferSource();selectionSource.buffer=buffer;selectionSource.connect(audioContext.destination);selectionSource.start(0,start/1000,(end-start)/1000);notice(`Playing selected phrase: ${(start/1000).toFixed(3)}–${(end/1000).toFixed(3)} seconds.`);});
$('player').onplay=stopSelection;$('player').ontimeupdate=draw;
let drag=null;const coordinate=e=>Math.round(Math.max(0,Math.min(1,(e.clientX-$('waveform').getBoundingClientRect().left)/$('waveform').getBoundingClientRect().width))*selected.duration_ms);
$('waveform').onpointerdown=e=>{if(!selected||!wave)return;drag=coordinate(e);$('waveform').setPointerCapture(e.pointerId);};$('waveform').onpointermove=e=>{if(drag===null)return;const at=coordinate(e);$('phraseStart').value=(Math.min(drag,at)/1000).toFixed(3);$('phraseEnd').value=(Math.max(drag,at)/1000).toFixed(3);dirty=true;draw();};$('waveform').onpointerup=$('waveform').onpointercancel=()=>{drag=null;};
$('retry').onclick=guard(async()=>{if(!selected)return;await send(`/api/training/recordings/${selected.id}/transcribe`,'POST');notice('Transcription queued. The review label stays unchanged.');const r=await api(`/api/training/recordings/${selected.id}`);transcript(r);});
new ResizeObserver(draw).observe($('waveform'));window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
guard(async()=>{const data=await api('/api/fleet');units=data.units;for(const u of units){$('collectionUnit').add(new Option(u.name+(u.online?'':' (offline)'),u.id));$('unitFilter').add(new Option(u.name,u.id));}$('manualListen').disabled=!units.length;await refreshStatus(true);await loadContext();await list();if(/^[a-f0-9]{32}$/.test(location.hash.slice(1)))await openRecord(location.hash.slice(1));})();
setInterval(()=>{refreshStatus().catch(()=>{});if(selected){const id=selected.id;api(`/api/training/recordings/${id}`).then(r=>{if(selected?.id===id)transcript(r);}).catch(()=>{});}},5000);
